mapper.select:
SELECT source_format AS format, object_key, size_bytes, sha256
FROM document_version
WHERE document_id = #{id} AND version_no = #{version}

SELECT block_index, text, page, chapter, section, metadata::text AS metadata_json
FROM document_parsed_block
WHERE document_id = #{id} AND document_version = #{version}
ORDER BY block_index
LIMIT #{limit}
OFFSET #{offset}

mapper.delete:
DELETE
FROM document_parsed_block
WHERE document_id = #{id} AND document_version = #{version}
